// Role gate (#219) — write-path scoping. Translates the role's `writeGlobs` into an anchored
// matcher and answers the two write-scope questions: may a role write a given PATH
// ({@link canWritePath}), and what is the effective write-scope boundary for a pane
// ({@link scopeWriteGlobs}, what the `bsc-scope` PreToolUse hook hard-limits to). Pure enforcement
// core, free of React / xterm / Tauri. Re-exported from `sessionRoles.ts`.

import type { RoleCapability, SessionRole } from "@/shared/lib/session/roleModel";
import { roleCapability, hasScopedWriteCarveOut } from "@/shared/lib/session/roleModel";

/**
 * The effective write-scope globs for a pane's role (#1297) — what the `bsc-scope` PreToolUse hook
 * hard-limits writes to. Uses the pane's assigned owned globs when it has them, else the role's
 * default boundary, so the planner falls back to {@link PLAN_WRITE_GLOBS} rather than being
 * overridden to `[]`. Empty ⇒ the role has no write boundary (a `code: "none"` role with no
 * carve-out, or a worker with no lane yet) and so gets no scope hook. A `code: "none"` role WITH an
 * explicit carve-out (the director's commons, #851) is scoped to exactly those globs — so the
 * scope hook hard-blocks any director write outside the commons.
 */
export function scopeWriteGlobs(role: SessionRole, ownGlobs: string[]): string[] {
  const cap = roleCapability(role, ownGlobs.length ? { writeGlobs: ownGlobs } : {});
  if (cap.code === "write") return cap.writeGlobs;
  return hasScopedWriteCarveOut(cap) ? cap.writeGlobs : [];
}

// ── Write-path scoping ──────────────────────────────────────────────────────────

/**
 * Translate a path glob into an anchored RegExp: `*` = non-slash run, `**` = any, `?` = exactly one
 * non-slash character, `[abc]` / `[!abc]` / `[a-c]` = a character class, and an UNTERMINATED `[` is a
 * literal bracket.
 *
 * `?` and `[` used to be metacharacter leaks in a security predicate
 * (`the-two-write-scope-glob-engines-disagree`). `?` was simply not handled: it fell through to the
 * `else` branch unescaped, so `src/a?.ts` compiled to `/^src\/a?\.ts$/` — "optional a" — and matched
 * `src/.ts` while failing to match `src/ab.ts`. `[` and `]` were ESCAPED, making a bracket expression
 * literal text. Both were the opposite of what the Rust matcher (`bsc_util::scope::fnmatch`) and the
 * shell hook (`scope.sh`'s `case`) do, and those are the engines that ENFORCE.
 *
 * Nothing in the packaged floors uses either character today, so this closes a latent divergence
 * rather than changing a live lane — six of the eight measured disagreements, none of them a real
 * glob. The remaining two are `*` crossing a separator, which cannot be settled here: see
 * `glob_parity.rs`.
 */
function globToRegExp(glob: string): RegExp {
  let out = "";
  for (let i = 0; i < glob.length; i++) {
    const c = glob[i];
    if (c === "*") {
      if (glob[i + 1] === "*") {
        out += ".*";
        i += 1;
      } else {
        out += "[^/]*";
      }
    } else if (c === "?") {
      // One character, and a separator is not one of them — the same rule `*` follows.
      out += "[^/]";
    } else if (c === "[" && closingBracket(glob, i) > i) {
      const end = closingBracket(glob, i);
      out += bracketClass(glob.slice(i, end + 1));
      i = end;
    } else if (/[.+^${}()|[\]\\?]/.test(c)) {
      out += `\\${c}`;
    } else {
      out += c;
    }
  }
  return new RegExp(`^${out}$`);
}

/** Index of the `]` closing the bracket expression opening at `from`, or `-1` when unterminated.
 *
 *  A `]` IMMEDIATELY after the opener (or after a leading `!`) is a literal member, not the close —
 *  the POSIX rule, and the same one `bsc_util::scope::bracket` follows. Without it `[]]` reads as an
 *  empty unterminated class. */
function closingBracket(glob: string, from: number): number {
  let i = from + 1;
  if (glob[i] === "!" || glob[i] === "^") i += 1;
  if (glob[i] === "]") i += 1;
  for (; i < glob.length; i++) if (glob[i] === "]") return i;
  return -1;
}

/** One bracket expression (`[abc]`, `[!abc]`, `[a-c]`) as a RegExp character class.
 *
 *  Only the negation marker is translated (`!` → `^`, which JS wants); the members are passed through
 *  because a glob class and a RegExp class already agree on ranges. A `^` inside is escaped so it
 *  cannot smuggle in a negation the glob did not write. */
function bracketClass(expr: string): string {
  let body = expr.slice(1, -1);
  let negated = false;
  if (body.startsWith("!") || body.startsWith("^")) {
    negated = true;
    body = body.slice(1);
  }
  const members = body.replace(/\\/g, "\\\\").replace(/\^/g, "\\^").replace(/\]/g, "\\]");
  return `[${negated ? "^" : ""}${members}]`;
}

/** True when `path` matches `glob`. */
export function matchGlob(glob: string, path: string): boolean {
  return globToRegExp(glob).test(path);
}

/**
 * Whether a role may write `path`: it needs `code` access AND the path must fall
 * inside one of its `writeGlobs`. No globs ⇒ no boundary ⇒ no code writes (a worker
 * must be assigned its ownership boundary first).
 *
 * The one exception is the scoped carve-out (#851): a `code: "none"` role that carries explicit
 * `writeGlobs` (the director's commons) may write paths inside those globs and nothing else — the
 * carve-out grants exactly the listed paths while every other write stays denied.
 */
export function canWritePath(cap: RoleCapability, path: string): boolean {
  if (cap.code === "none" && !hasScopedWriteCarveOut(cap)) return false;
  return cap.writeGlobs.some((g) => matchGlob(g, path));
}
